<?php
require_once __DIR__.'/proforma-pdf-render.php';
require_once __DIR__.'/proforma-contract-template.php';
function qcSource($db,$id){
 $s=$db->prepare('SELECT p.*,c.Cliente,c.DniRuc AS Documento,c.Direccion AS ClienteDireccion FROM Ve_Proforma p JOIN Ve_DocVentaCliente c ON c.IdCliente=p.IdCliente WHERE p.IdProforma=? AND COALESCE(p.Anulado,0)=0');$s->execute([$id]);$quote=$s->fetch(PDO::FETCH_ASSOC);
 if(!$quote||($quote['Presentacion']??'')!=='sistemas')throw new InvalidArgumentException('Selecciona una proforma de sistemas disponible.');
 $s=$db->prepare('SELECT d.Cantidad,d.Precio,d.Descuento,d.DisabledTotal,d.Descripcion,g.Producto,g.ProductoDesc,g.ProductoDesc2,g.ProductoDesc3 FROM Ve_ProformaDet d JOIN Gen_Producto g ON g.IdProducto=d.IdProducto WHERE d.IdProforma=? ORDER BY d.IdProducto,d.Precio,d.Cantidad,d.Descripcion');$s->execute([$id]);$products=$s->fetchAll(PDO::FETCH_ASSOC);
 if(!$products)throw new InvalidArgumentException('La propuesta no contiene productos.');
 $company=$db->query('SELECT RAZONSOCIAL,RUC,DIRECCION,TELEFONO,CELULAR,EMAIL FROM GEN_EMPRESA WHERE IDEMPRESA=1')->fetch(PDO::FETCH_ASSOC);
 if(!$company)throw new InvalidArgumentException('Configura los datos de la empresa.');
 return ['quote'=>$quote,'products'=>$products,'company'=>$company];
}
function qcHash($source){return hash('sha256',json_encode($source,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE));}
function qcTotal($products){$total=0;foreach($products as $p)$total+=(float)$p['Cantidad']*(float)$p['Precio']-(float)$p['Descuento'];if(!is_finite($total)||$total<=0||$total>999999999)throw new InvalidArgumentException('El total de la propuesta debe ser mayor a cero.');return (int)round($total*100);}
function qcDate($value){if(!is_string($value))return false;$date=DateTimeImmutable::createFromFormat('!Y-m-d',$value);return $date&&$date->format('Y-m-d')===$value;}
function qcInput($body,$source){
 if(!is_array($body))throw new InvalidArgumentException('Revisa los datos del contrato.');$out=[];$body+=['consultor'=>qpConsultantName(),'representanteProveedor'=>qpManagerName()];
 foreach(['AlcanceSistema','EntregablesSistema','CondicionesSistema'] as $key)if(trim((string)($source['quote'][$key]??''))==='')throw new InvalidArgumentException('Completa primero el alcance, implementación y condiciones de la proforma.');
 $limits=['cliente'=>180,'documento'=>20,'direccion'=>500,'representanteCliente'=>180,'representanteProveedor'=>180,'consultor'=>180,'vigenciaLicencia'=>1000,'plazoImplementacion'=>1000,'pagoSaldo'=>1500,'condicionesEspeciales'=>6000,'medioAdelanto'=>120,'referenciaAdelanto'=>120];
 foreach($limits as $key=>$limit){$v=$body[$key]??'';if(!is_string($v)||mb_strlen($v)>$limit||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f]/',$v))throw new InvalidArgumentException('Revisa el campo '.$key.'.');$out[$key]=trim($v);}
 foreach(['cliente','documento','direccion','consultor','representanteProveedor','vigenciaLicencia','plazoImplementacion','pagoSaldo'] as $key)if($out[$key]==='')throw new InvalidArgumentException('Completa los datos del cliente, vigencia, implementación y pago del saldo.');
 if(preg_match('/^CLIENTE[S]?\s+VARIOS?$/iu',$out['cliente'])||!preg_match('/^[A-Za-z0-9-]{6,20}$/D',$out['documento'])||preg_match('/^0+$/D',$out['documento']))throw new InvalidArgumentException('Identifica al cliente con su nombre o razón social y documento real.');
 if(!qcDate($body['fecha']??null))throw new InvalidArgumentException('Indica una fecha de contrato válida.');$out['fecha']=$body['fecha'];
 $due=$body['fechaSaldo']??'';if(!is_string($due)||($due!==''&&!qcDate($due)))throw new InvalidArgumentException('Indica una fecha válida para el pago del saldo.');$out['fechaSaldo']=$due;
 $out['recibido']=($body['recibido']??false)===true;if($out['recibido']){if(!qcDate($body['fechaAdelanto']??null)||$out['medioAdelanto']==='')throw new InvalidArgumentException('Indica fecha y medio del adelanto recibido.');$out['fechaAdelanto']=$body['fechaAdelanto'];}else{$out['fechaAdelanto']='';$out['medioAdelanto']='';$out['referenciaAdelanto']='';}
 $total=qcTotal($source['products']);$mode=$body['modoAdelanto']??'porcentaje';$value=$body['adelanto']??50;
 if(!in_array($mode,['porcentaje','monto'],true)||(!is_int($value)&&!is_float($value)&&!is_string($value))||!is_numeric($value)||!is_finite((float)$value)||(float)$value<0)throw new InvalidArgumentException('Revisa el adelanto.');
 if($mode==='porcentaje'){if((float)$value>100)throw new InvalidArgumentException('El adelanto no puede superar el 100 %.');$advance=(int)round($total*(float)$value/100);}else{if((float)$value>$total/100)throw new InvalidArgumentException('El adelanto no puede superar el total.');$advance=(int)round((float)$value*100);}
 if($advance>$total||($out['recibido']&&$advance===0))throw new InvalidArgumentException('El adelanto debe estar entre cero y el total del contrato.');
 if(($body['revisado']??false)!==true)throw new InvalidArgumentException('Revisa y confirma los términos antes de generar el contrato.');
 $out['modoAdelanto']=$mode;$out['adelanto']=(float)$value;$out['totalCentimos']=$total;$out['adelantoCentimos']=$advance;$out['saldoCentimos']=$total-$advance;$out['revisado']=true;
 return array_merge($out,qcTemplateInput($body,$source));
}
function qcSaveDraft($db,$id,$source,$input,$user){
 $s=$db->prepare('SELECT COALESCE(MAX(Version),0)+1 FROM Ve_ProformaContrato WHERE IdProforma=?');$s->execute([$id]);$version=(int)$s->fetchColumn();
 $data=['source'=>$source,'form'=>$input,'version'=>$version,'templateVersion'=>2,'paymentAccountsImage'=>qcPaymentMode($input)!=='texto'?qcPaymentImage():null,'consultantSignature'=>!empty($input['incluirRubricaConsultor'])?qpConsultantRubric($input['consultor']):null,'modulePresentation'=>qpModulePresentation($source['quote']['AlcanceSistema']??''),'annualPresentation'=>qpAnnualPlanPresentation($source['quote']['CondicionesSistema']??'')];$s=$db->prepare('INSERT INTO Ve_ProformaContrato(IdProforma,Version,Datos,SourceHash,Usuario,Fecha) VALUES(?,?,?,?,?,NOW())');$s->execute([$id,$version,json_encode($data,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),qcHash($source),$user]);return ['id'=>(int)$db->lastInsertId(),'version'=>$version,'data'=>$data];
}
function qcMoney($cents){return qpMoney($cents/100);}
function qcHtml($data){
 return ($data['templateVersion']??1)>=2?qcCorporateHtml($data):qcHtmlLegacy($data);
}
function qcHtmlLegacy($data){
 $source=$data['source'];$q=$source['quote'];$c=$source['company'];$f=$data['form'];$number=$q['Anio'].'-'.$q['Numero'].' / V'.(int)$data['version'];$logo=dirname(__DIR__).'/nuevo/static/images/proforma-logo-color.png';if(!is_file($logo))$logo=dirname(__DIR__,2).'/static/images/proforma-logo-color.png';$logoHtml=is_file($logo)?'<img width="150" src="data:image/png;base64,'.base64_encode(file_get_contents($logo)).'">':'';
 $section=function($title,$text){return trim((string)$text)!==''?'<h2>'.qpEscape($title).'</h2><div class="copy">'.nl2br(qpEscape($text)).'</div>':'';};
 $modules=$data['modulePresentation']??qpModulePresentation($q['AlcanceSistema']??'');$annual=$data['annualPresentation']??qpAnnualPlanPresentation($q['CondicionesSistema']??'');$modules['text']=preg_replace('/^Propuesta para\s+/imu','Propuesta de sistemas de ',$modules['text']);
 $html='<html><head><meta charset="UTF-8"><style>@page{margin:12mm 14mm}body{font-family:DejaVu Sans,sans-serif;font-size:9px;color:#45343b;line-height:1.45}table{width:100%;border-collapse:collapse}td{vertical-align:top}.brand td{vertical-align:middle}.provider{text-align:right;font-size:8px;color:#765d68}.draft{font-size:8px;letter-spacing:.7px;color:#a8223c;border-top:3px solid #b61f38;padding-top:10px;margin-top:15px}h1{font-size:17px;line-height:1.3;color:#a51e35;margin:6px 0}h2{font-size:10px;color:#ab233b;border-bottom:1px solid #ead8df;padding-bottom:5px;margin:12px 0 6px;page-break-after:avoid}h3{font-size:9px;margin:7px 0 3px}.copy{font-size:9px;line-height:1.6}.parties{background:#fff7f9;border-left:3px solid #b31e38;margin:14px 0}.parties td{padding:10px;width:50%;font-size:8.5px}.parties b{display:block;margin-bottom:4px}.label{color:#976b7b;font-size:7px}.periods{margin:10px 0;page-break-inside:avoid}.periods td{width:50%;padding:8px;border:1px solid #eee0e5;font-size:8.5px}.periods b{color:#a3233c}.payment{margin:10px 0;page-break-inside:avoid}.payment td{padding:10px;border:1px solid #ead7de;width:33%;font-size:8px}.payment strong{display:block;font-size:16px;color:#aa1f38;margin-top:5px}.payment .remaining{background:#fff3f6}.notice{padding:8px;background:#fff8fa;border-left:2px solid #bb2943;font-size:8px;margin:10px 0}.signatures{margin-top:18px;page-break-inside:avoid}.signatures td{width:50%;padding:10px;font-size:8px;text-align:center}.signatures b{display:block;border-top:1px solid #927a85;padding-top:7px}.modules{margin:6px 0}.modules tr{page-break-inside:avoid}.modules ul{margin:3px 0;padding-left:13px}.modules li{margin:0 0 2px}.modules td{padding:6px;border-bottom:1px solid #f0e3e7;font-size:8px}.modules b{display:block}.services td{width:50%;padding:3px;line-height:1.4;border-bottom:1px solid #eee0e5;font-size:8px}.services tr{page-break-inside:avoid}.services b{display:block;margin-bottom:3px}.annual{padding:10px;border:1px solid #dcb9c3;background:#fff9fa;margin:10px 0;page-break-inside:avoid}.annual h3{font-size:12px;color:#a7223b}.annual-price{font-size:17px;color:#a51e35;font-weight:bold}.footer{position:fixed;bottom:-20px;left:0;right:0;border-top:1px solid #eadce2;color:#8a6f7c;font-size:7px;margin-top:0;padding-top:4px;line-height:1.3}.contract-three .parties{margin:10px 0}.contract-three .parties td{padding:8px}.contract-three h2{margin-top:10px}.contract-three .annual{padding:8px;margin:8px 0}.contract-three .annual p{margin:7px 0}.contract-three .services td{padding:2px 3px;line-height:1.35}.contract-close{page-break-inside:avoid}.signatures-three{table-layout:fixed;margin-top:12px}.signatures-three td{width:33.333%;padding:0 9px;font-size:8px;vertical-align:top}.signature-space{height:40px}.signatures-three .signature-name{font-size:9px;line-height:1.45;color:#45343b}.signature-role{display:block;font-size:7px;letter-spacing:.6px;color:#ab233b;margin:5px 0 4px}.signature-note{display:block;font-size:7px;color:#8a6f7c}</style></head><body'.(isset($f['consultor'])?' class="contract-three"':'').'><table class="brand"><tr><td>'.$logoHtml.'</td><td class="provider"><b>'.qpEscape($c['RAZONSOCIAL']).'</b><br>RUC '.qpEscape($c['RUC']).'<br>'.qpEscape($c['TELEFONO'].' · '.$c['CELULAR']).'<br>'.qpEscape($c['EMAIL']).'</td></tr></table><div class="draft">BORRADOR PARA REVISIÓN Y FIRMA · CONTRATO '.$number.'</div><h1>CONTRATO DE LICENCIA Y SERVICIOS DE SISTEMAS</h1><div>'.qpEscape(qpSystemTitle($q['AlcanceSistema']??'',$source['products'])).'</div><p>Fecha: '.qpEscape((new DateTimeImmutable($f['fecha']))->format('d/m/Y')).' · Proforma de referencia: '.qpEscape($q['Anio'].'-'.$q['Numero']).'</p><table class="parties"><tr><td><span class="label">PROVEEDOR</span><b>'.qpEscape($c['RAZONSOCIAL']).'</b>RUC: '.qpEscape($c['RUC']).'<br>Domicilio: '.qpEscape($c['DIRECCION']).($f['representanteProveedor']!==''?'<br>'.(isset($f['consultor'])?'Gerente general: ':'Representante: ').qpEscape($f['representanteProveedor']):'').(isset($f['consultor'])?'<br>Consultor: '.qpEscape($f['consultor']):'').'</td><td><span class="label">CLIENTE</span><b>'.qpEscape($f['cliente']).'</b>Documento: '.qpEscape($f['documento']).'<br>Domicilio: '.qpEscape($f['direccion']).($f['representanteCliente']!==''?'<br>Representante legal: '.qpEscape($f['representanteCliente']):'').'</td></tr></table>';
 $html.=$section('01 · Objeto y solución contratada','El proveedor y el cliente dejan descritos en este documento la licencia, el alcance y los servicios correspondientes a la proforma indicada. Los términos están sujetos a revisión y aceptación de ambas partes.');
 foreach($source['products'] as $p){$html.='<h3>'.qpEscape($p['Producto']).'</h3><div class="copy">Cantidad: '.qpEscape($p['Cantidad']).'</div>';foreach(array_unique(array_filter([$p['ProductoDesc']??'',$p['ProductoDesc2']??'',$p['ProductoDesc3']??'',$p['Descripcion']??''])) as $detail)$html.='<div class="copy">'.nl2br(qpEscape($detail)).'</div>';}
 $html.=$section('02 · Alcance y módulos incluidos',$modules['text']);if($modules['modules']){$html.='<table class="modules">';foreach($modules['modules'] as $m)$html.='<tr><td><b>'.qpEscape($m['name']).'</b>'.qpEscape($m['description']).(!empty($m['features'])?'<ul><li>'.implode('</li><li>',array_map('qpEscape',$m['features'])).'</li></ul>':'').'</td></tr>';$html.='</table>';}
 $html.=$section('03 · Implementación y entregables',$q['EntregablesSistema']??'').'<table class="periods"><tr><td><b>Vigencia de la licencia</b><br>'.nl2br(qpEscape($f['vigenciaLicencia'])).'</td><td><b>Plazo de implementación</b><br>'.nl2br(qpEscape($f['plazoImplementacion'])).'</td></tr></table>';
 $html.='<h2>04 · Inversión, adelanto y saldo</h2><table class="payment"><tr><td>PRECIO TOTAL ACORDADO<strong>'.qcMoney($f['totalCentimos']).'</strong></td><td>'.($f['recibido']?'ADELANTO DECLARADO RECIBIDO':'ADELANTO PACTADO').'<strong>'.qcMoney($f['adelantoCentimos']).'</strong></td><td class="remaining">SALDO DESPUÉS DEL ADELANTO<strong>'.qcMoney($f['saldoCentimos']).'</strong></td></tr></table>'.$section('Pago del saldo',$f['pagoSaldo']);
 if(array_key_exists('fechaSaldo',$f))$html.='<div class="copy"><b>Fecha de pago del saldo:</b> '.($f['fechaSaldo']!==''?qpEscape((new DateTimeImmutable($f['fechaSaldo']))->format('d/m/Y')):'pendiente de acuerdo con el cliente.').'</div>';
 if($f['recibido'])$html.='<div class="notice">El vendedor declara recibido el adelanto el '.qpEscape((new DateTimeImmutable($f['fechaAdelanto']))->format('d/m/Y')).', mediante '.qpEscape($f['medioAdelanto']).($f['referenciaAdelanto']!==''?' · Referencia: '.qpEscape($f['referenciaAdelanto']):'').'. Este documento no reemplaza el comprobante de pago correspondiente.</div>';else $html.='<div class="notice">El adelanto indicado corresponde al acuerdo de pago. Este borrador no acredita su recepción.</div>';
 $html.=$section('05 · Servicios, soporte y condiciones',$annual['text']);
 if($annual['plan']){$plan=$annual['plan'];$html.='<div class="annual"><h3>Plan Anual Integral de Facturación Electrónica</h3><div class="annual-price">'.qpEscape($plan['price']).' al año</div>';foreach($plan['terms'] as $term)$html.='<p>'.qpEscape($term).'</p>';$html.='</div><table class="services">';foreach(array_chunk($plan['services'],2) as $row){$html.='<tr>';foreach($row as $service)$html.='<td><b>'.qpEscape($service['name']).'</b>'.qpEscape($service['description']).'</td>';if(count($row)===1)$html.='<td></td>';$html.='</tr>';}$html.='</table>';}
 $html.=$section('06 · Acuerdos particulares',$f['condicionesEspeciales']).'<div class="contract-close">'.$section('07 · Revisión y aceptación','Las partes revisarán y suscribirán los términos de este documento. Los cambios de alcance o importes se acordarán por escrito. Este borrador está pendiente de aceptación y firma.');
 $html.=array_key_exists('consultor',$f)?qcSignaturesHtml($f):'<table class="signatures"><tr><td><b>POR EL PROVEEDOR</b>'.qpEscape($f['representanteProveedor']?:$c['RAZONSOCIAL']).'<br>Firma y documento</td><td><b>POR EL CLIENTE</b>'.qpEscape($f['representanteCliente']?:$f['cliente']).'<br>Firma y documento</td></tr></table>';
 $html.='</div><div class="footer">Contrato basado en la proforma '.qpEscape($q['Anio'].'-'.$q['Numero']).' · Versión '.(int)$data['version'].' · Borrador para revisión de las partes.</div></body></html>';
 return $html;
}

function qcSignaturesHtml($form,$rubric=null){
 $signers=[[$form['consultor'],$form['cargoConsultor']??'CONSULTOR','Firma / rúbrica'],[$form['representanteCliente']?:$form['cliente'],$form['representanteCliente']!==''?'REPRESENTANTE LEGAL DEL CLIENTE':'CLIENTE','Firma y documento'],[$form['representanteProveedor'],'GERENTE GENERAL','Firma / sello del proveedor']];
 $html='<table class="signatures signatures-three" aria-label="Consultor, cliente y gerente general"><tr>';
 foreach($signers as $i=>$signer){$document=$form[['documentoConsultor','documentoRepresentanteCliente','documentoRepresentanteProveedor'][$i]]??'';if($i===1&&$form['representanteCliente']==='')$document=$form['documento'];$html.='<td><div class="signature-space">'.($i===0?qpRubricImage($rubric):'').'</div><b class="signature-name">'.qpEscape($signer[0]).'</b><span class="signature-role">'.qpEscape($signer[1]).'</span>'.($document!==''?'<span class="signature-document">Documento: '.qpEscape($document).'</span>':'').'<span class="signature-note">'.qpEscape($signer[2]).'</span></td>';}
 return $html.'</tr></table>';
}
